sys_script_include.script:
var IncentIQImportProcessor = Class.create();
IncentIQImportProcessor.prototype = {
    initialize: function() {},

    start: function(batchId) {
        var result = {
            success: false,
            runSysId: ''
        };

        var staging = new GlideRecordSecure('x_ctans_incentnow_data_lake_staging');
        staging.addQuery('sys_import_set', batchId);
        staging.setLimit(1);
        staging.query();

        if (!staging.next()) {
            result.message = 'No staging records found.';
            gs.info("IncentIQImportProcessor - ERROR: No staging records found");
            return result;
        }

        var runGR = new GlideRecordSecure('x_ctans_incentnow_import_run');
        runGR.initialize();
        runGR.setValue('status', 'Running');
        runGR.setValue('batch_id', batchId);
        runGR.setValue('data_model_object', staging.getValue('data_model_object'));
        runGR.setValue('run_by', gs.getUserID());
        runGR.setValue('started_at', new GlideDateTime());
        var runSysId = runGR.insert();
        gs.addInfoMessage("Import Run Created: " + runGR.number);

        gs.eventQueue(
            'x_ctans_incentnow.process_import',
            runGR,
            runSysId,
            batchId
        );

        result.success = true;
        result.runSysId = runSysId;
        result.message = 'Import processing started.';
        return result;
    },

    type: 'IncentIQImportProcessor'
};
